# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">OKULUN BÖLÜMLERİ (أَقْسَامُ الْمَدْرَسَةِ) VE MEKÂN İFADELERİ</text>\n  <rect x="20" y="45" width="210" height="95" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">الْإِدَارَةُ وَالْمُعَلِّمُونَ</text>\n  <text x="125" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">İdari Birimler</text>\n  <text x="125" y="108" text-anchor="middle" font-size="10.5" fill="#1d4ed8">غُرْفَةُ الْمُدِيرِ (Müdür Odası)</text>\n  <text x="125" y="126" text-anchor="middle" font-size="10.5" fill="#1d4ed8">غُرْفَةُ الْمُعَلِّمِينَ (Öğretmenler Odası)</text>\n  <rect x="245" y="45" width="210" height="95" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">قَاعَاتُ التَّعْلِيمِ</text>\n  <text x="350" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Eğitim ve Uygulama Alanları</text>\n  <text x="350" y="108" text-anchor="middle" font-size="10.5" fill="#166534">الْمَكْتَبَةُ (Kütüphane) · الْمُخْتَبَرُ (Laboratuvar)</text>\n  <text x="350" y="126" text-anchor="middle" font-size="10.5" fill="#166534">قَاعَةُ الْحَاسُوبِ (Bilgisayar Sınıfı)</text>\n  <rect x="470" y="45" width="210" height="95" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">الْمَرَافِقُ الْأُخْرَى</text>\n  <text x="575" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">Ortak Kullanım Alanları</text>\n  <text x="575" y="108" text-anchor="middle" font-size="10.5" fill="#78350f">الْمَقْصَفُ (Kantin) · الْمَسْجِدُ (Mescit)</text>\n  <text x="575" y="126" text-anchor="middle" font-size="10.5" fill="#78350f">حَدِيقَةُ الْمَدْرَسَةِ (Okul Bahçesi) · الْمَلْعَبُ</text>\n  <rect x="20" y="152" width="660" height="92" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="175" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">KATLAR (الطَّوَابِقُ) VE YÖN / KONUM BİLDİREN KALIPLAR</text>\n  <text x="40" y="200" font-size="11" font-weight="bold" fill="#581c87">• الطَّابِقُ الْأَوَّلُ (Birinci kat) · الطَّابِقُ الثَّانِي (İkinci kat) · الطَّابِقُ الثَّالِثُ (Üçüncü kat)</text>\n  <text x="40" y="224" font-size="11" font-weight="bold" fill="#581c87">• أَيْنَ الْمَكْتَبَةُ؟ ← الْمَكْتَبَةُ فِي الطَّابِقِ الثَّانِي بِجَانِبِ الْمُخْتَبَرِ. (Kütüphane 2. katta laboratuvarın yanındadır.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DERSLERİM (دُرُوسِي) VE HAFTALIK DERS PROGRAMI (جَدْوَلُ الدُّرُوسِ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">الدُّرُوسُ (DERS ADLARI)</text>\n  <text x="35" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">• اللُّغَةُ الْعَرَبِيَّةُ (Arapça) · اللُّغَةُ التُّرْكِيَّةُ (Türkçe)</text>\n  <text x="35" y="118" font-size="11" font-weight="bold" fill="#1e3a8a">• الرِّيَاضِيَّاتُ (Matematik) · التَّارِيخُ (Tarih)</text>\n  <text x="35" y="142" font-size="11" font-weight="bold" fill="#1e3a8a">• الْفِيزِيَاءُ (Fizik) · الْكِيمِيَاءُ (Kimya) · الْأَحْيَاءُ (Biyoloji)</text>\n  <text x="35" y="166" font-size="11" font-weight="bold" fill="#1e3a8a">• الْجُغْرَافِيَا (Coğrafya) · الْقُرْآنُ الْكَرِيمُ (Kur\'an-ı Kerim)</text>\n  <text x="35" y="190" font-size="11" font-weight="bold" fill="#1e3a8a">• التَّرْبِيَةُ الْبَدَنِيَّةُ (Beden Eğitimi) · الْمُوسِيقَى (Müzik)</text>\n  <text x="35" y="216" font-size="10.5" font-weight="bold" fill="#b91c1c">• أُحِبُّ دَرْسَ اللُّغَةِ الْعَرَبِيَّةِ. (Arapça dersini seviyorum.)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">أَيَّامُ الْأُسْبُوعِ (HAFTANIN GÜNLERİ)</text>\n  <text x="378" y="96" font-size="11" font-weight="bold" fill="#166534">• يَوْمُ الْإِثْنَيْنِ (Pazartesi) · يَوْمُ الثُّلَاثَاءِ (Salı)</text>\n  <text x="378" y="120" font-size="11" font-weight="bold" fill="#166534">• يَوْمُ الْأَرْبِعَاءِ (Çarşamba) · يَوْمُ الْخَمِيسِ (Perşembe)</text>\n  <text x="378" y="144" font-size="11" font-weight="bold" fill="#166534">• يَوْمُ الْجُمُعَةِ (Cuma) — [Okul Günleri]</text>\n  <text x="378" y="168" font-size="11" font-weight="bold" fill="#b45309">• يَوْمُ السَّبْتِ (Cumartesi) · يَوْمُ الْأَحَدِ (Pazar) [Tatil]</text>\n  <rect x="375" y="182" width="290" height="46" rx="8" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="388" y="202" font-size="10.5" font-weight="bold" fill="#14532d">الْحِصَّةُ الْأُولَى (1. Ders) · الْحِصَّةُ الثَّانِيَةُ (2. Ders)</text>\n  <text x="388" y="220" font-size="10.5" font-weight="bold" fill="#166534">الْحِصَّةُ الثَّالِثَةُ (3. Ders) · الْحِصَّةُ الرَّابِعَةُ (4. Ders)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SAATLER (السَّاعَاتُ) VE DERS ZAMANI SORULARI (مَتَى / فِي أَيِّ سَاعَةٍ؟)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">كَمِ السَّاعَةُ؟ (SAAT KAÇ? — SIRA SAYILARIYLA)</text>\n  <text x="35" y="94" font-size="10.5" font-weight="bold" fill="#78350f">• السَّاعَةُ الْوَاحِدَةُ (01.00) · السَّاعَةُ الثَّانِيَةُ (02.00)</text>\n  <text x="35" y="116" font-size="10.5" font-weight="bold" fill="#78350f">• السَّاعَةُ الثَّالِثَةُ (03.00) · السَّاعَةُ الرَّابِعَةُ (04.00)</text>\n  <text x="35" y="138" font-size="10.5" font-weight="bold" fill="#78350f">• السَّاعَةُ الْخَامِسَةُ (05.00) · السَّاعَةُ السَّادِسَةُ (06.00)</text>\n  <text x="35" y="160" font-size="10.5" font-weight="bold" fill="#78350f">• السَّاعَةُ السَّابِعَةُ (07.00) · السَّاعَةُ الثَّامِنَةُ (08.00)</text>\n  <text x="35" y="182" font-size="10.5" font-weight="bold" fill="#78350f">• السَّاعَةُ التَّاسِعَةُ (09.00) · السَّاعَةُ الْعَاشِرَةُ (10.00)</text>\n  <text x="35" y="204" font-size="10.5" font-weight="bold" fill="#78350f">• الْحَادِيَةَ عَشْرَةَ (11.00) · الثَّانِيَةَ عَشْرَةَ (12.00)</text>\n  <text x="35" y="226" font-size="10.5" font-weight="bold" fill="#b91c1c">• وَالنِّصْفُ (Buçuk: .30) · وَالرُّبْعُ (Çeyrek geçiyor: .15)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">DERS BAŞLANGIÇ VE SAAT DİYALOGLARI</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#581c87">• فِي أَيِّ سَاعَةٍ يَبْدَأُ الدَّرْسُ الْأَوَّلُ؟</text>\n  <text x="375" y="114" font-size="10.5" fill="#6b21a8">(Birinci ders saat kaçta başlıyor?)</text>\n  <text x="375" y="140" font-size="11" font-weight="bold" fill="#581c87">• يَبْدَأُ الدَّرْسُ فِي السَّاعَةِ الثَّامِنَةِ وَالنِّصْفِ.</text>\n  <text x="375" y="158" font-size="10.5" fill="#6b21a8">(Ders saat sekiz buçukta [08.30] başlıyor.)</text>\n  <text x="375" y="186" font-size="11" font-weight="bold" fill="#581c87">• مَتَى يَنْتَهِي الدَّوَامُ الْمَدْرَسِيُّ؟</text>\n  <text x="375" y="204" font-size="10.5" fill="#6b21a8">(Okul mesaisi ne zaman bitiyor?)</text>\n  <text x="375" y="224" font-size="10.5" font-weight="bold" fill="#15803d">• يَنْتَهِي فِي السَّاعَةِ الثَّالِثَةِ وَالرُّبْعِ (15.15).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
